local real_client, real_ui, real_globals_table = client, ui, _G
local runtime = {created_items = 0, callback_errors = 0, optional_modules = {}}
local function pack(...) return {n = select("#", ...), ...} end
local function log(...) real_client.log("[Outlaw local] " .. table.concat({...}, " ")) end
local function guard(callback, event)
    return function(...)
        if (event == "setup_command" or event == "run_command" or event == "predict_command") and entity.get_local_player() == nil then return end
        local result = pack(pcall(callback, ...))
        if result[1] then return unpack(result, 2, result.n) end
        runtime.callback_errors = runtime.callback_errors + 1
        if runtime.callback_errors <= 3 then log(event .. ": " .. tostring(result[2])) end
    end
end
local client = setmetatable({}, {__index = real_client})
local callbacks = {}
function client.set_event_callback(event, callback)
    callbacks[event] = callbacks[event] or {}
    if not callbacks[event][callback] then
        local wrapped = guard(callback, event)
        callbacks[event][callback] = wrapped
        real_client.set_event_callback(event, wrapped)
    end
end
function client.unset_event_callback(event, callback)
    local wrapped = callbacks[event] and callbacks[event][callback]
    if wrapped then real_client.unset_event_callback(event, wrapped); callbacks[event][callback] = nil end
end
local ui = setmetatable({}, {__index = real_ui})
local item_kinds, item_specs = {}, {}
local function copy_options(args, first, last)
    local options = {}
    if type(args[first]) == "table" then
        for i, value in ipairs(args[first]) do options[i] = value end
    else
        for i = first, last do options[#options + 1] = args[i] end
    end
    return options
end
function ui.set(item, value, ...)
    if item_kinds[item] == "new_multiselect" and type(value) == "table" then
        return real_ui.set(item, unpack(value))
    end
    return real_ui.set(item, value, ...)
end
for _, name in ipairs({"new_button", "new_checkbox", "new_color_picker", "new_combobox", "new_hotkey", "new_label", "new_listbox", "new_multiselect", "new_slider", "new_string", "new_textbox"}) do
    local constructor = real_ui[name]
    ui[name] = function(...)
        local args = pack(...)
        while args.n > 0 and args[args.n] == nil do args.n = args.n - 1 end
        local result
        if name == "new_listbox" then
            local items = args[4]
            if type(items) ~= "table" then
                items = {}
                for i = 4, args.n do items[#items + 1] = args[i] end
            end
            result = constructor(args[1], args[2], args[3], items)
        else
            result = constructor(unpack(args, 1, args.n))
        end
        runtime.created_items = runtime.created_items + 1
        item_kinds[result] = name
        local spec = {kind = name, name = args[3]}
        if name == "new_combobox" or name == "new_multiselect" or name == "new_listbox" then
            spec.options = copy_options(args, 4, args.n)
        elseif name == "new_slider" then
            spec.min, spec.max = args[4], args[5]
        end
        item_specs[result] = spec
        return result
    end
end
function ui.update(item, ...)
    local args = pack(...)
    while args.n > 0 and args[args.n] == nil do args.n = args.n - 1 end
    local options = copy_options(args, 1, args.n)
    real_ui.update(item, options)
    if item_specs[item] then item_specs[item].options = options end
end

local compatibility = {applied = 0, skipped = 0, adjusted = 0}
runtime.config_compatibility = compatibility
local function option_key(value)
    return value:gsub("\7%x%x%x%x%x%x%x%x", ""):match("^%s*(.-)%s*$"):lower()
end
local function find_option(options, requested)
    if type(requested) ~= "string" then return nil end
    for _, option in ipairs(options) do if option == requested then return option end end
    local key, found = option_key(requested), nil
    for _, option in ipairs(options) do
        if option_key(option) == key then
            if found then return nil end  
            found = option
        end
    end
    return found
end
local function import_config_control(control, values)
    if type(values) ~= "table" then return false, "Config entry must contain a value list" end
    local spec = item_specs[control.reference]
    local args, count = values, #values
    if spec and spec.kind == "new_combobox" then
        local value = find_option(spec.options, values[1])
        if value == nil then
            compatibility.skipped = compatibility.skipped + 1
            return true  
        end
        if value ~= values[1] then compatibility.adjusted = compatibility.adjusted + 1 end
        args, count = {value}, 1
    elseif spec and spec.kind == "new_multiselect" then
        local requested = type(values[1]) == "table" and values[1] or values
        local selected, seen = {}, {}
        for _, requested_value in ipairs(requested) do
            local value = find_option(spec.options, requested_value)
            if value == nil then
                compatibility.skipped = compatibility.skipped + 1
            elseif not seen[value] then
                seen[value] = true
                selected[#selected + 1] = value
                if value ~= requested_value then compatibility.adjusted = compatibility.adjusted + 1 end
            end
        end
        args, count = {selected}, 1
    elseif spec and spec.kind == "new_slider" then
        local value = values[1]
        if type(value) ~= "number" or value ~= value then
            return false, "Invalid numeric config value for " .. spec.name
        end
        local bounded = math.max(spec.min, math.min(spec.max, value))
        if bounded ~= value then compatibility.adjusted = compatibility.adjusted + 1 end
        args, count = {bounded}, 1
    end
    local ok, err = pcall(control.set, control, unpack(args, 1, count))
    if ok then compatibility.applied = compatibility.applied + 1 end
    return ok, err
end
local function wrap_config_import(importer)
    return function(...)
        local skipped, adjusted = compatibility.skipped, compatibility.adjusted
        local result = pack(importer(...))
        skipped, adjusted = compatibility.skipped - skipped, compatibility.adjusted - adjusted
        if skipped > 0 or adjusted > 0 then
            log("Config compatibility: " .. skipped .. " unavailable options skipped, " .. adjusted .. " values adjusted")
        end
        return unpack(result, 1, result.n)
    end
end

