local function create_clipboard_adapter()
    local provider
    local function acquire()
        if provider then return provider end
        local ok, module = pcall(require, "gamesense/clipboard")
        if ok and type(module) == "table" and type(module.get) == "function" and type(module.set) == "function" then
            provider = module
            return provider
        end
        local ffi = require("ffi")
        local interface = client.create_interface("vgui2.dll", "VGUI_System010")
        assert(interface ~= nil, "Clipboard interface VGUI_System010 is unavailable")
        local pointer = ffi.cast("void***", interface)
        local get_count = ffi.cast("int(__thiscall*)(void*)", pointer[0][7])
        local set_text = ffi.cast("void(__thiscall*)(void*, const char*, int)", pointer[0][9])
        local get_text = ffi.cast("int(__thiscall*)(void*, int, char*, int)", pointer[0][11])
        local buffer_type = ffi.typeof("char[?]")
        provider = {
            get = function()
                local length = get_count(pointer)
                if length <= 1 then return "" end
                assert(length <= 1048576, "Clipboard text is too large for a config")
                local buffer = buffer_type(length)
                get_text(pointer, 0, buffer, length)
                return ffi.string(buffer, length - 1)
            end,
            set = function(text)
                assert(type(text) == "string", "Clipboard contents must be a string")
                set_text(pointer, text, #text)
            end,
        }
        return provider
    end
    return {
        export = function(text) acquire().set(text) end,
        import = function() return acquire().get() or "" end,
    }
end


