doubleto8bytes = function(x)
	local function grab_byte(v)
		return math_floor(v / 256), tostr(math_fmod(math_floor(v), 256))
	end
	local sign = 0
	if x < 0 then sign = 1; x = -x end
	local mantissa, exponent = math_frexp(x)
	if x == 0 then  
		mantissa, exponent = 0, 0
	elseif x == 1/0 then
		mantissa, exponent = 0, 2047
	else
		mantissa = (mantissa * 2 - 1) * math_ldexp(0.5, 53)
		exponent = exponent + 1022
	end

	local v, byte = ""  
	x = mantissa
	for i = 1,6 do
		x, byte = grab_byte(x); v = v..byte  
	end
	x, byte = grab_byte(exponent * 16 + x);  v = v..byte  
	x, byte = grab_byte(sign * 128 + x); v = v..byte  
	return v
end

