		band( v:byte(7), 15 ), v:byte(6), v:byte(5), v:byte(4), v:byte(3), v:byte(2), v:byte(1)  
	}
	local bits = bytestobits(fracbytes)

	for i=1,4 do table_remove(bits,1) end


	if sign == 1 then sign = -1 else sign = 1 end

	local frac = bitstofrac(bits)
	if exp == -1023 and frac==0 then return 0 end
	if exp == 1024 and frac==0 then return 1/0 *sign end
	local real = math_ldexp(1+frac,exp)

	return real * sign
end


local packers = {}

packers.dynamic = function(data)
	local t = type(data)
	return packers[t](data)
end

packers["nil"] = function(data)
	table_insert( strary, tostr(0xc0))
end

packers.boolean = function(data)
	if data then  
		table_insert( strary, tostr(0xc3))
	else  
		table_insert( strary, tostr(0xc2))
	end
end

packers.number = function(n)
	if math_floor(n) == n then  
		if n >= 0 then  
			if n < 128 then  
				 table_insert( strary, tostr(n))
			elseif n < 256 then  
				 table_insert(strary, tostr(0xcc,n))
			elseif n < 65536 then  
				strary_append_int16(n,0xcd)
			elseif n < 4294967296 then  
				strary_append_int32(n,0xce)
			else  
				 strary_append_double(n)
			end
		else  
			if n >= -32 then  
				 table_insert( strary, tostr( 0xe0 + ((n+256)%32)) )
			elseif n >= -128 then  
				 table_insert( strary, tostr(0xd0,byte_mod(n,0x100)))
			elseif n >= -32768 then  
				strary_append_int16(n,0xd1)
			elseif n >= -2147483648 then  
				strary_append_int32(n,0xd2)
			else  
				 strary_append_double(n)
			end
		end
	else  
		 strary_append_double(n)
	end
end

packers.string = function(data)
	local n = #data
	if n < 32 then
		 table_insert( strary, tostr( 0xa0+n ) )
	elseif n < 65536 then
		strary_append_int16(n,0xda)
	elseif n < 4294967296 then
		strary_append_int32(n,0xdb)
	else
		error("overflow")
	end
	table_insert( strary, data)
end

packers["function"] = function(data)
	error("unimplemented:function")
end

packers.userdata = function(data)
	error("unimplemented:userdata")
end

packers.thread = function(data)
	error("unimplemented:thread")
end

packers.table = function(data)
	local is_map,ndata,nmax = false,0,0
	for k,_ in pairs(data) do
		if type(k) == "number" then
			if k > nmax then nmax = k end
		else is_map = true end
		ndata = ndata+1
	end
	if is_map then  
		if ndata < 16 then
			 table_insert( strary, tostr(0x80+ndata))
		elseif ndata < 65536 then
			strary_append_int16(ndata,0xde)
		elseif ndata < 4294967296 then
			strary_append_int32(ndata,0xdf)
		else
			error("overflow")
		end
		for k,v in pairs(data) do
			packers[type(k)](k)
			packers[type(v)](v)
		end
	else  
		if nmax < 16 then
			 table_insert( strary, tostr( 0x90+nmax ) )
		elseif nmax < 65536 then
			strary_append_int16(nmax,0xdc)
		elseif nmax < 4294967296 then
			strary_append_int32(nmax,0xdd)
		else
			error("overflow")
		end
		for i=1,nmax do packers[type(data[i])](data[i]) end
	end
end


local types_map = {
		[0xc0] = "nil",
		[0xc2] = "false",
		[0xc3] = "true",
		[0xca] = "float",
		[0xcb] = "double",
		[0xcc] = "uint8",
		[0xcd] = "uint16",
		[0xce] = "uint32",
		[0xcf] = "uint64",
		[0xd0] = "int8",
		[0xd1] = "int16",
		[0xd2] = "int32",
		[0xd3] = "int64",
		[0xda] = "raw16",
		[0xdb] = "raw32",
		[0xdc] = "array16",
		[0xdd] = "array32",
