local function vtable_bind(dll, interface_name, index, signature)
    local ok, object = pcall(real_client.create_interface, dll, interface_name)
    if not ok or object == nil then
        return function() return nil end
    end
    local pointer = ffi.cast("void***", object)
    local method = ffi.cast(signature, pointer[0][index])
    return function(...) return method(object, ...) end
end

